 import { configV2Schema, FILESYSTEM_DOCUMENT_TOOLS, FILESYSTEM_ISSUE_TOOLS, formatSchemaError } from './schemas.js';

 export type ConfigDocument = Record<string, unknown>;

 export class ConfigError extends Error {
   public constructor(message: string) {
     super(message);
     this.name = 'ConfigError';
   }
 }

 const CONFIG_PATH = join('.harnessctl', 'config.yaml');
 export const DEFAULT_CONFIG: ConfigDocument = {
   version: 2,
   issues: {
     root: '.harnessctl/issues',
     prefix: 'hrn-',
     type: 'filesystem',
     tools: FILESYSTEM_ISSUE_TOOLS,
   },
